div.script:
(function(){
"use strict";
var R = document.getElementById('alv-rrhh');
if(!R || R.dataset.init) return; R.dataset.init = "1";
var TZ = -5*3600000;
var TEC = /^(Administrator|Administrador|Sucursal .* - |Gerente de Operaciones)/i;
var TOL = 5;
var TARDANZAS_DESDE = '2026-11-13';   // el conteo arranca a partir de este día
var S = {tab:'home', fecha:null, mes:null, semana:null,
         emp:[], att:[], attRango:[], cal:[], calLin:[], slots:[], leaves:[], ultima:null,
         q:'', sede:'', area:'', est:'', gq:'', gfalta:'', hq:'', tq:'', edit:null, edith:null, abAreas:{}, nvoT:false, abierto:{}};

function rpc(model, method, args, kwargs){
  return fetch('/web/dataset/call_kw', {
    method:'POST', headers:{'Content-Type':'application/json'},
    body: JSON.stringify({jsonrpc:"2.0", method:"call",
      params:{model:model, method:method, args:args, kwargs:kwargs||{}}})
  }).then(function(r){ return r.json(); }).then(function(j){
    if(j.error) throw new Error((j.error.data && j.error.data.message) || j.error.message || 'Error');
    return j.result;
  });
}
function pad(n){ return (n<10?'0':'')+n; }
function local(u){ return u ? new Date(u.replace(' ','T')+'Z').getTime()+TZ : null; }
function hhmm(ms){ if(ms==null) return '—'; var d=new Date(ms); return pad(d.getUTCHours())+':'+pad(d.getUTCMinutes()); }
function minHHMM(m){ if(m==null) return '—'; return pad(Math.floor(m/60))+':'+pad(Math.round(m%60)); }
function esc(s){ return String(s==null?'':s).replace(/[&<>"]/g,function(c){
  return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]; }); }
function hoyL(){ var n=new Date(Date.now()+TZ);
  return n.getUTCFullYear()+'-'+pad(n.getUTCMonth()+1)+'-'+pad(n.getUTCDate()); }
function iso(ms){ var d=new Date(ms);
  return d.getUTCFullYear()+'-'+pad(d.getUTCMonth()+1)+'-'+pad(d.getUTCDate()); }
function aUTC(f, hhmmStr){
  var ms = new Date(f+'T'+(hhmmStr||'00:00')+':00Z').getTime() - TZ, d=new Date(ms);
  return d.getUTCFullYear()+'-'+pad(d.getUTCMonth()+1)+'-'+pad(d.getUTCDate())+' '+
         pad(d.getUTCHours())+':'+pad(d.getUTCMinutes())+':'+pad(d.getUTCSeconds());
}
var MES=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
var DIA=['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
var DIA3=['Dom','Lun','Mar','Mié','Jue','Vie','Sáb'];
function larga(f){ var d=new Date(f+'T12:00:00Z');
  return DIA[d.getUTCDay()]+' '+d.getUTCDate()+' de '+MES[d.getUTCMonth()]+' de '+d.getUTCFullYear(); }
function lunesDe(f){
  var d = new Date(f+'T12:00:00Z'), dow = (d.getUTCDay()+6)%7;
  d.setUTCDate(d.getUTCDate()-dow); return iso(d.getTime());
}
function masDias(f,n){ var d=new Date(f+'T12:00:00Z'); d.setUTCDate(d.getUTCDate()+n); return iso(d.getTime()); }

function cargar(){
  var b = document.getElementById('a-body');
  b.innerHTML = '<div class="a-load">Cargando…</div>';
  if(!S.fecha) S.fecha = hoyL();
  if(!S.mes)   S.mes   = S.fecha.slice(0,7);
  if(!S.semana) S.semana = lunesDe(S.fecha);
  var d0 = aUTC(S.fecha,'00:00'), d1 = aUTC(masDias(S.fecha,1),'00:00');
  var r0 = aUTC(masDias(S.fecha,-30),'00:00');
  var s0 = aUTC(S.semana,'00:00'), s1 = aUTC(masDias(S.semana,7),'00:00');
  Promise.all([
    rpc('hr.employee','search_read',[[['active','=',true]],
      ['name','identification_id','department_id','company_id','job_title',
       'resource_calendar_id','birthday','private_phone','mobile_phone','country_id']],{limit:500}),
    rpc('hr.attendance','search_read',[[['check_in','>=',d0],['check_in','<',d1]],
      ['employee_id','check_in','check_out']],{limit:2000,order:'check_in'}),
    rpc('hr.attendance','search_read',[[['check_in','>=',r0],['check_in','<',d1]],
      ['employee_id','check_in','check_out']],{limit:5000,order:'check_in'}),
    rpc('resource.calendar','search_read',[[],['name','hours_per_day','tz']],{limit:60}),
    rpc('resource.calendar.attendance','search_read',[[],
      ['calendar_id','dayofweek','hour_from','hour_to','day_period']],{limit:900}),
    rpc('planning.slot','search_read',[[['start_datetime','>=',s0],['start_datetime','<',s1]],
      ['employee_id','start_datetime','end_datetime','state','allocated_hours']],{limit:600})
      .catch(function(){ return []; }),
    rpc('hr.leave','search_read',[[['date_from','<=',d1],['date_to','>=',r0]],
      ['employee_id','holiday_status_id','date_from','date_to','state','number_of_days']],{limit:600})
      .catch(function(){ return []; }),
    rpc('hr.attendance','search_read',[[],['check_in']],{limit:1,order:'check_in desc'}),
    rpc('hr.department','search_read',[[],['name','complete_name']],{limit:400}).catch(function(){ return []; }),
    rpc('ir.config_parameter','search_read',[[['key','=','alvina.rrhh_turnos']],['value']],{limit:1}).catch(function(){ return []; })
  ]).then(function(r){
    S.emp=r[0]; S.att=r[1]; S.attRango=r[2]; S.cal=r[3]; S.calLin=r[4];
    S.slots=r[5]; S.leaves=r[6]; S.ultima=r[7][0]||null; S.dept=r[8]||[];
    // cargar turnos adicionales guardados antes
    try{
      var cu = (r[9] && r[9][0] && r[9][0].value) ? JSON.parse(r[9][0].value) : [];
      TURNOS = TURNOS_BASE.concat(cu.filter(function(t){
        return t && t.id && t.nombre && t.entra && t.sale; }));
    }catch(e){ TURNOS = TURNOS_BASE.slice(); }
    pintar();
  }).catch(function(e){
    b.innerHTML = '<div class="a-alert"><div><b>No se pudieron leer los datos.</b><br>'+esc(e.message)+
      '<br><br>Si eres de Recursos Humanos y ves esto, pide que te agreguen al grupo '+
      '<b>Recursos Humanos → Administrador</b> en tu usuario de Odoo.</div></div>';
  });
}

function personas(){
  return S.emp.filter(function(e){ return !TEC.test(e.name); }).map(function(e){
    return {id:e.id, nombre:e.name, dni:e.identification_id||null,
      cargo:e.job_title||null,
      area:e.department_id ? e.department_id[1].split(' / ').pop() : null,
      deptId:e.department_id ? e.department_id[0] : null,
      sede:e.company_id ? e.company_id[1] : null,
      calId:e.resource_calendar_id ? e.resource_calendar_id[0] : null,
      horario:e.resource_calendar_id ? e.resource_calendar_id[1] : null,
      cumple:e.birthday||null, tel:e.private_phone||e.mobile_phone||null,
      pais:e.country_id?e.country_id[1]:null};
  });
}
function jornadaDe(att){
  var m = {};
  att.forEach(function(a){
    var id=a.employee_id[0], o=m[id];
    if(!o){ m[id]={ci:a.check_in, co:a.check_out||null, n:1}; return; }
    if(a.check_in < o.ci) o.ci=a.check_in;
    if(a.check_out && (!o.co || a.check_out>o.co)) o.co=a.check_out;
    o.n++;
  });
  return m;
}
function esperada(p, fecha){
  var dow = String((new Date(fecha+'T12:00:00Z').getUTCDay()+6)%7);
  var sl = S.slots.filter(function(s){
    return s.employee_id && s.employee_id[0]===p.id && s.state==='published' &&
           iso(local(s.start_datetime))===fecha; });
  if(sl.length){ var ms=local(sl[0].start_datetime), d=new Date(ms);
    return {min:d.getUTCHours()*60+d.getUTCMinutes(), origen:'turno publicado'}; }
  if(!p.calId) return null;
  var lin = S.calLin.filter(function(l){
    return l.calendar_id[0]===p.calId && String(l.dayofweek)===dow && l.day_period!=='lunch'; });
  if(!lin.length) return null;
  var h = Math.min.apply(null, lin.map(function(l){ return l.hour_from; }));
  return {min: Math.round(h*60), origen:'horario fijo'};
}
function deDescanso(p, fecha){
  return S.leaves.some(function(l){
    if(!l.employee_id || l.employee_id[0]!==p.id) return false;
    if(['refuse','cancel'].indexOf(l.state)>-1) return false;
    return iso(local(l.date_from)) <= fecha && fecha <= iso(local(l.date_to));
  });
}
function yaDebioEntrar(p){
  if(S.fecha !== hoyL()) return true;
  var esp = esperada(p, S.fecha);
  if(!esp) return false;
  var n = new Date(Date.now()+TZ);
  return (n.getUTCHours()*60 + n.getUTCMinutes()) > esp.min + 30;
}
function calcularTardanzas(P){
  var porEmp = {};
  S.attRango.forEach(function(a){
    var f = iso(local(a.check_in));
    var k = a.employee_id[0]+'|'+f;
    if(!porEmp[k] || a.check_in < porEmp[k]) porEmp[k] = a.check_in;
  });
  return P.map(function(p){
    var dias = [], sinHorario = false;
    Object.keys(porEmp).forEach(function(k){
      var part = k.split('|');
      if(+part[0] !== p.id) return;
      var fecha = part[1];
      if(fecha < TARDANZAS_DESDE) return;
      if(deDescanso(p, fecha)) return;
      var esp = esperada(p, fecha);
      if(!esp){ sinHorario = true; return; }
      var ms = local(porEmp[k]), d = new Date(ms);
      var real = d.getUTCHours()*60 + d.getUTCMinutes();
      var retraso = real - esp.min;
      if(retraso > TOL) dias.push({fecha:fecha, real:real, esp:esp.min, min:retraso, origen:esp.origen});
    });
    dias.sort(function(a,b){ return a.fecha < b.fecha ? 1 : -1; });
    return {p:p, dias:dias, total:dias.length,
      minutos: dias.reduce(function(s,d){ return s+d.min; },0), sinHorario:sinHorario};
  });
}

function pintar(){
  var P = personas(), esHoy = S.fecha===hoyL();
  var jor = jornadaDe(S.att);
  document.getElementById('a-fecha').textContent =
    larga(S.fecha) + (esHoy?' · hoy':'') + ' · ' + P.length + ' personas activas';
  var h = '';
  if(S.ultima){
    var u = local(S.ultima.check_in);
    var dias = Math.round((new Date(hoyL()+'T00:00:00Z').getTime() -
                           new Date(iso(u)+'T00:00:00Z').getTime())/86400000);
    if(dias>=1) h += '<div class="a-alert"><div><b>El asistómetro no está sincronizando.</b> '+
      'La última marcación es del '+larga(iso(u))+' a las '+hhmm(u)+', hace '+dias+' día'+(dias>1?'s':'')+
      '. Avisa a Sistemas: hasta que vuelva, estas pantallas no tendrán datos nuevos.</div></div>';
  }
  var sinM = P.filter(function(p){ return !jor[p.id] && !deDescanso(p, S.fecha) &&
                                           p.calId && yaDebioEntrar(p); }).length;
  var abiertas = 0;   // ya no contamos jornadas abiertas como pendiente de hoy
  var incompletas = P.filter(function(p){ return faltantes(p).length>0; }).length;
  var sinHorario = P.filter(function(p){ return !p.calId; }).length;
  var T = calcularTardanzas(P);
  var conTardanza = T.filter(function(t){ return t.total>0; }).length;

  // Datos para los contadores de los módulos
  var ctx = {P:P, jor:jor, T:T, conTardanza:conTardanza, sinHorario:sinHorario,
             incompletas:incompletas, pendientes: sinM+abiertas, conCumple:P.filter(function(p){ return p.cumple; }).length};

  var tit = document.getElementById('a-titulo');
  tit.textContent = S.tab==='home' ? 'Personal' : TITULOS[S.tab]||'Personal';

  var b = document.getElementById('a-body');
  if(S.tab==='home'){
    b.innerHTML = h + '<div id="a-pane"></div>';
    paneHome(ctx);
    return;
  }
  b.innerHTML = h +
    '<button class="a-back" id="a-back" type="button">← Volver al inicio</button>'+
    '<div id="a-pane"></div>';
  document.getElementById('a-back').onclick = function(){ S.tab='home'; pintar(); };
  ({asis:paneAsistencia, tard:paneTardanzas, cump:paneCumples,
    hora:paneHorarios, fich:paneFicha, aler:paneAlertas}[S.tab])(P, jor, T);
}
var TITULOS = {asis:'Asistencia', tard:'Tardanzas', cump:'Cumpleaños',
               hora:'Horarios y descansos', fich:'Ficha del personal', aler:'Pendientes de hoy'};

function paneHome(c){
  var mods = [
    {id:'asis', t:'Asistencia', d:'Quiénes marcaron hoy, con su entrada, salida y horas. Filtra por sede, área y estado.',
     n:c.P.length, cl:'', m:'personas activas', ac:'Abrir →'},
    {id:'tard', t:'Tardanzas', d:'Ranking de quiénes llegan tarde en los últimos 30 días, con el detalle día por día.',
     n:c.conTardanza, cl:c.conTardanza?'wa':'ok', m:'con tardanzas', ac:'Revisar →'},
    {id:'cump', t:'Cumpleaños', d:'Calendario mensual con el nombre de cada persona en el día en que cumple.',
     n:c.conCumple, cl:'', m:'de '+c.P.length+' registrados', ac:'Ver calendario →'},
    {id:'hora', t:'Horarios y descansos', d:'Define quién entra a qué hora, revisa si el horario asignado se parece a la hora real y arma turnos variables por semana.',
     n:c.sinHorario, cl:c.sinHorario?'cr':'ok', m:c.sinHorario?'sin horario':'todos asignados', ac:'Configurar →'},
    {id:'fich', t:'Ficha del personal', d:'Qué dato le falta a cada trabajador — documento, cumpleaños, teléfono, área, cargo u horario.',
     n:c.incompletas, cl:c.incompletas?'wa':'ok', m:'incompletas', ac:'Completar →'},
    {id:'aler', t:'Pendientes de hoy', d:'Jornadas abiertas y personas que no marcaron. Lo que hay que resolver hoy mismo.',
     n:c.pendientes, cl:c.pendientes?'cr':'ok', m:'por revisar', ac:'Ver →'},
    {id:'reclu', t:'Reclutamiento', d:'Procesos de selección, publicación de vacantes y seguimiento de postulantes. En construcción.',
     n:'—', cl:'blk', m:'Próximamente', ac:'Bloqueado', bloqueado:true}
  ];
  var h = '<div class="a-grid">';
  mods.forEach(function(m){
    h += '<div class="a-mod'+(m.bloqueado?' dis':'')+'" data-m="'+m.id+'">'+
      '<div class="a-mod-h"><div class="a-mod-t">'+(m.bloqueado?'🔒 ':'')+m.t+'</div>'+
        '<div class="a-mod-n '+m.cl+'">'+m.n+'</div></div>'+
      '<div class="a-mod-d">'+m.d+'</div>'+
      '<div class="a-mod-f"><span class="a-mod-m">'+m.m+'</span>'+
        '<span class="a-mod-a">'+m.ac+'</span></div></div>';
  });
  h += '</div>';
  document.getElementById('a-pane').innerHTML = h;
  Array.prototype.forEach.call(pane().querySelectorAll('.a-mod'), function(m){
    if(m.classList.contains('dis')){
      m.onclick = function(){ mensaje('Este módulo está en construcción.','cr'); };
      return;
    }
    m.onclick = function(){ S.tab = m.getAttribute('data-m'); pintar(); };
  });
}
function tab(id,l,n){ return '<div class="a-tab'+(S.tab===id?' on':'')+'" data-t="'+id+'">'+
  l+'<span class="n">'+n+'</span></div>'; }
function guia(txt){ return '<p class="a-guia">'+txt+'</p>'; }
function kpi(l,v,d,c){ return '<div class="a-kpi '+(c||'')+'"><div class="l">'+l+'</div>'+
  '<div class="v">'+v+'</div><div class="d">'+d+'</div></div>'; }
function sel(id,val,ph,opts){
  var h='<select id="'+id+'"><option value="">'+ph+'</option>';
  opts.forEach(function(o){ var v=(o instanceof Array)?o[0]:o, l=(o instanceof Array)?o[1]:o;
    h+='<option value="'+esc(v)+'"'+(String(val)===String(v)?' selected':'')+'>'+esc(l)+'</option>'; });
  return h+'</select>';
}
function pane(){ return document.getElementById('a-pane'); }
function buscador(id, val, ph){
  return '<input type="text" id="'+id+'" placeholder="'+ph+'" value="'+esc(val)+'">';
}
function ligarBuscador(id, campo){
  var q = pane().querySelector('#'+id);
  if(!q) return;
  q.oninput = function(){ var p=q.selectionStart; S[campo]=q.value; pintar();
    var n=document.getElementById(id); if(n){ n.focus(); try{n.setSelectionRange(p,p);}catch(e){} } };
}

function paneAsistencia(P, jor){
  var h = guia('Quiénes marcaron hoy y a qué hora. Cambia la fecha para ver otro día. '+
    'Las jornadas que cruzan medianoche quedan en el día en que empezó el turno.');
  var sedes=[], areas=[];
  P.forEach(function(p){ if(p.sede&&sedes.indexOf(p.sede)<0) sedes.push(p.sede);
                         if(p.area&&areas.indexOf(p.area)<0) areas.push(p.area); });
  sedes.sort(); areas.sort();
  h += '<div class="a-fl">'+
    '<input type="date" id="f-fecha" value="'+S.fecha+'">'+
    buscador('f-q', S.q, 'Buscar por nombre o documento…')+
    sel('f-sede',S.sede,'Todas las sedes',sedes)+
    sel('f-est',S.est,'Todos los estados',[['ok','Entrada y salida'],['abierta','Entrada sin salida'],
      ['no','No marcó'],['desc','De descanso']])+'</div>';

  // armar lista con filtros aplicados
  var L = P.map(function(p){
    var j = jor[p.id], ci=j?local(j.ci):null, co=j&&j.co?local(j.co):null;
    var desc = deDescanso(p, S.fecha);
    return {p:p, ci:ci, co:co, desc:desc,
      horas:(ci!=null&&co!=null)?(co-ci)/3600000:null,
      estado: desc?'desc' : !j?'no' : co?'ok':'abierta'};
  }).filter(function(r){
    if(S.sede && r.p.sede!==S.sede) return false;
    if(S.est && r.estado!==S.est) return false;
    if(S.q){ var q=S.q.toLowerCase();
      if(r.p.nombre.toLowerCase().indexOf(q)<0 && String(r.p.dni||'').indexOf(q)<0) return false; }
    return true;
  });

  // agrupar por área
  var GA = {};
  L.forEach(function(r){ var k = r.p.area || '(Sin área)'; (GA[k]=GA[k]||[]).push(r); });
  var ordenA = Object.keys(GA).sort(function(a,b){ return a.localeCompare(b); });

  if(!ordenA.length){
    h += '<div class="a-card"><div class="a-empty">Nadie coincide con el filtro.</div></div>';
    pane().innerHTML = h;
  } else {
    ordenA.forEach(function(areaN){
      var lista = GA[areaN].sort(function(a,b){ return (a.ci==null?Infinity:a.ci) - (b.ci==null?Infinity:b.ci); });
      var ab = !!S.abAreas[areaN];
      var marc = lista.filter(function(r){ return r.estado==='ok' || r.estado==='abierta'; }).length;
      h += '<div class="a-grp'+(ab?' on':'')+'" data-area="'+esc(areaN)+'">'+
           '<div class="a-grp-h" data-act="area">'+
           '<span class="ar">▸</span>'+esc(areaN)+
           '<span class="a-grp-n">'+marc+' marcaron · '+lista.length+' en total</span>'+
           '</div><div class="a-grp-body">';
      h += '<div class="a-card"><div class="a-sc"><table class="a-t"><thead><tr>'+
        '<th>Empleado</th><th>Sede</th><th>Entrada</th><th>Salida</th><th>Horas</th><th>Estado</th>'+
        '</tr></thead><tbody>';
      lista.forEach(function(r){
        var cruzaDia = (r.ci!=null && r.co!=null && iso(r.ci)!==iso(r.co));
        var sospechosa = cruzaDia && r.horas!=null && r.horas > 10;
        var pil;
        if(sospechosa) pil = '<span class="pill p-cr" title="Cruzó medianoche y dura más de 10 h. Puede que no haya marcado una entrada o una salida.">Revisar</span>';
        else if(r.estado==='ok')      pil = '<span class="pill p-ok">Completa</span>';
        else if(r.estado==='abierta') pil = '<span class="pill p-wa">Sin salida</span>';
        else if(r.estado==='desc')    pil = '<span class="pill p-gr">Descanso</span>';
        else                          pil = '<span class="pill p-cr">No marcó</span>';
        h += '<tr><td><div class="nm">'+esc(r.p.nombre)+'</div><div class="sm">'+
          (r.p.dni?'Doc. '+esc(r.p.dni):'sin documento')+'</div></td>'+
          '<td>'+esc(r.p.sede||'—')+'</td>'+
          '<td class="hr">'+hhmm(r.ci)+'</td>'+
          '<td class="hr">'+hhmm(r.co)+
            (r.co!=null && r.ci!=null && iso(r.co)!==iso(r.ci)
               ? ' <span class="sm" style="color:var(--ac);font-weight:700">+1 día</span>' : '')+
          '</td>'+
          '<td class="hr">'+(r.horas!=null?r.horas.toFixed(1)+' h':'—')+'</td><td>'+pil+'</td></tr>';
      });
      h += '</tbody></table></div></div></div></div>';
    });
    pane().innerHTML = h;
  }

  ligarBuscador('f-q','q');
  ['sede','est'].forEach(function(f){
    var el=pane().querySelector('#f-'+f); if(el) el.onchange=function(){ S[f]=el.value; pintar(); }; });
  var fd = pane().querySelector('#f-fecha');
  if(fd) fd.onchange = function(){ if(fd.value){ S.fecha=fd.value; cargar(); } };
  // alternar apertura de cada área (igual que en Horarios)
  Array.prototype.forEach.call(pane().querySelectorAll('.a-grp-h[data-act=area]'), function(hd){
    hd.onclick = function(){
      var grp = hd.closest('.a-grp'); if(!grp) return;
      var area = grp.getAttribute('data-area');
      S.abAreas[area] = !S.abAreas[area]; pintar();
    };
  });
}

function paneTardanzas(P, jor, T){
  var h = guia('Quién llega tarde, en los últimos 30 días. Se compara la primera marca del día '+
    'contra la hora de entrada de su horario, con '+TOL+' minutos de tolerancia. '+
    'Los días de descanso registrado no cuentan. El conteo arranca el '+
    larga(TARDANZAS_DESDE).replace(/^./, function(c){ return c.toUpperCase(); })+
    ', así que los días anteriores no se toman en cuenta. Haz clic en una fila para ver los días.');
  var sinH = P.filter(function(p){ return !p.calId; }).length;
  if(sinH) h += '<div class="a-alert"><div><b>'+sinH+' personas no tienen horario asignado</b>, '+
    'así que no se les puede medir tardanza. Ve a la pestaña <b>Horarios</b> y asígnales uno.</div></div>';
  var L = T.filter(function(t){ return t.total>0; })
           .sort(function(a,b){ return b.total-a.total || b.minutos-a.minutos; });
  h += '<div class="a-kpis">'+
    kpi('Con tardanzas', L.length, 'de '+P.length+' personas', L.length?'wa':'ok')+
    kpi('Tardanzas totales', L.reduce(function(s,t){return s+t.total;},0), 'últimos 30 días','')+
    kpi('Minutos acumulados', L.reduce(function(s,t){return s+t.minutos;},0), 'suma de todos','')+
  '</div>';
  h += '<div class="a-fl">'+buscador('t-q', S.tq, 'Buscar persona…')+'</div>';
  var F = L.filter(function(t){ return !S.tq ||
    t.p.nombre.toLowerCase().indexOf(S.tq.toLowerCase())>-1; });
  h += '<div class="a-card"><div class="a-sc"><table class="a-t"><thead><tr>'+
    '<th>Empleado</th><th>Sede</th><th>Horario</th><th>Tardanzas</th><th>Minutos</th><th></th>'+
    '</tr></thead><tbody>';
  if(!F.length) h += '<tr><td colspan="6"><div class="a-empty">'+
    (sinH===P.length ? 'Primero asigna horarios en la pestaña Horarios.'
                     : 'Nadie registra tardanzas en este período.')+'</div></td></tr>';
  F.forEach(function(t){
    var ab = !!S.abierto[t.p.id];
    h += '<tr class="cl" data-emp="'+t.p.id+'"><td><div class="nm">'+esc(t.p.nombre)+'</div></td>'+
      '<td>'+esc(t.p.sede||'—')+'</td><td class="sm">'+esc(t.p.horario||'sin horario')+'</td>'+
      '<td class="hr">'+t.total+'</td><td class="hr">'+t.minutos+' min</td>'+
      '<td class="hr">'+(ab?'▾':'▸')+'</td></tr>';
    if(ab){
      h += '<tr><td colspan="6" class="det"><table class="a-sub"><thead><tr>'+
        '<th>Día</th><th>Debía entrar</th><th>Entró</th><th>Tarde</th><th>Según</th></tr></thead><tbody>';
      t.dias.forEach(function(d){
        h += '<tr><td>'+larga(d.fecha).replace(' de '+new Date(d.fecha+'T12:00:00Z').getUTCFullYear(),'')+'</td>'+
          '<td class="hr">'+minHHMM(d.esp)+'</td><td class="hr">'+minHHMM(d.real)+'</td>'+
          '<td class="hr"><b>'+d.min+' min</b></td><td class="sm">'+d.origen+'</td></tr>';
      });
      h += '</tbody></table></td></tr>';
    }
  });
  h += '</tbody></table></div></div>';
  pane().innerHTML = h;
  ligarBuscador('t-q','tq');
  Array.prototype.forEach.call(pane().querySelectorAll('tr.cl'), function(tr){
    tr.onclick = function(){ var id=tr.getAttribute('data-emp');
      S.abierto[id] = !S.abierto[id]; pintar(); };
  });
}

function paneCumples(P){
  var h = guia('Calendario de cumpleaños. Cambia de mes con las flechas. '+
    'Quien no tenga fecha registrada no aparece: están listados en Ficha del personal.');
  var conF = P.filter(function(p){ return p.cumple; });
  var y = +S.mes.slice(0,4), m = +S.mes.slice(5,7);
  var porDia = {};
  conF.forEach(function(p){
    var mm = +p.cumple.slice(5,7), dd = +p.cumple.slice(8,10);
    if(mm===m) (porDia[dd]=porDia[dd]||[]).push(p);
  });
  h += '<div class="a-mes">'+
    '<button class="a-btn" id="m-ant" type="button">‹</button>'+
    '<div class="a-mes-t">'+MES[m-1].charAt(0).toUpperCase()+MES[m-1].slice(1)+' '+y+'</div>'+
    '<button class="a-btn" id="m-sig" type="button">›</button>'+
    '<div class="a-mes-n">'+Object.keys(porDia).reduce(function(s,k){return s+porDia[k].length;},0)+
    ' cumpleaños este mes</div></div>';
  var primero = new Date(Date.UTC(y,m-1,1)), offset = (primero.getUTCDay()+6)%7;
  var ultimo = new Date(Date.UTC(y,m,0)).getUTCDate();
  var hoy = hoyL();
  h += '<div class="a-cal">';
  ['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].forEach(function(d){ h += '<div class="a-cab">'+d+'</div>'; });
  for(var i=0;i<offset;i++) h += '<div class="a-dia vacio"></div>';
  for(var d=1; d<=ultimo; d++){
    var f = y+'-'+pad(m)+'-'+pad(d);
    var gente = porDia[d]||[];
    h += '<div class="a-dia'+(gente.length?' hay':'')+(f===hoy?' hoy':'')+'">'+
      '<div class="a-num">'+d+'</div>'+
      gente.map(function(p){
        var edad = y - (+p.cumple.slice(0,4));
        return '<div class="a-cum" title="'+esc(p.nombre)+' · cumple '+edad+'">'+
          esc(p.nombre.split(/\s+/).slice(-2).join(' '))+'</div>'; }).join('')+
      '</div>';
  }
  h += '</div>';
  var sinF = P.length - conF.length;
  if(sinF) h += '<p class="a-foot"><b>'+sinF+' personas no tienen fecha de nacimiento registrada</b>, '+
    'así que no salen en el calendario. Las APIs de consulta por documento no devuelven ese dato, '+
    'así que hay que pedírselo a cada trabajador. La lista está en Ficha del personal.</p>';
  pane().innerHTML = h;
  var a=pane().querySelector('#m-ant'), s=pane().querySelector('#m-sig');
  if(a) a.onclick=function(){ var mm=m-1,yy=y; if(mm<1){mm=12;yy--;} S.mes=yy+'-'+pad(mm); pintar(); };
  if(s) s.onclick=function(){ var mm=m+1,yy=y; if(mm>12){mm=1;yy++;} S.mes=yy+'-'+pad(mm); pintar(); };
}

var TURNOS_BASE = [
  {id:'madrugada', nombre:'Madrugada',            entra:'04:00', sale:'13:00', hpd:9},
  {id:'temprano',  nombre:'Producción temprano',  entra:'05:30', sale:'14:30', hpd:9},
  {id:'manana',    nombre:'Mañana',               entra:'07:00', sale:'16:00', hpd:9},
  {id:'admin',     nombre:'Administrativo',       entra:'08:00', sale:'18:00', hpd:9, lunch:true},
  {id:'tarde',     nombre:'Tarde',                entra:'14:00', sale:'22:00', hpd:8}
];
var TURNOS = TURNOS_BASE.slice();   // se extiende con los que agrega RR. HH. desde la pantalla
var DIAS_FULL = ['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'];
function clasificarCalendar(cal){
  // detecta a qué turno y día de descanso corresponde un resource.calendar
  if(!cal) return {turno:null, descanso:null};
  var lin = S.calLin.filter(function(l){ return l.calendar_id[0]===cal && l.day_period!=='lunch'; });
  if(!lin.length) return {turno:null, descanso:null};
  var ent = Math.min.apply(null, lin.map(function(l){ return l.hour_from; }));
  var hhmm = pad(Math.floor(ent))+':'+pad(Math.round((ent-Math.floor(ent))*60));
  var turno = null;
  TURNOS.forEach(function(t){ if(t.entra === hhmm) turno = t; });
  var dows = {}; lin.forEach(function(l){ dows[String(l.dayofweek)] = 1; });
  var falta = [];
  for(var d=0; d<7; d++){ if(!dows[String(d)]) falta.push(d); }
  var descanso = falta.length===1 ? falta[0] : null;
  return {turno:turno, descanso:descanso};
}

function guardarTurnoNuevo(nombre, entra, sale){
  // validar
  if(!nombre || nombre.length < 3) return Promise.reject(new Error('El nombre tiene que tener al menos 3 letras.'));
  if(!/^[0-2][0-9]:[0-5][0-9]$/.test(entra) || !/^[0-2][0-9]:[0-5][0-9]$/.test(sale))
    return Promise.reject(new Error('Las horas van en formato HH:MM.'));
  var h1 = parseInt(entra.slice(0,2))*60 + parseInt(entra.slice(3,5));
  var h2 = parseInt(sale.slice(0,2))*60 + parseInt(sale.slice(3,5));
  if(h2 <= h1) return Promise.reject(new Error('La salida debe ser después de la entrada. Los turnos nocturnos que cruzan medianoche hay que configurarlos en Odoo directamente.'));
  var id = 'c_' + Date.now();
  var hpd = Math.round((h2-h1)/60 * 10) / 10;
  var nuevo = {id:id, nombre:nombre.trim(), entra:entra, sale:sale, hpd:hpd};
  // añadir y persistir
  TURNOS.push(nuevo);
  var custom = TURNOS.filter(function(t){ return t.id.indexOf('c_')===0; });
  return rpc('ir.config_parameter','search_read',[[['key','=','alvina.rrhh_turnos']],['id']],{limit:1})
    .then(function(ex){
      if(ex.length) return rpc('ir.config_parameter','write',[[ex[0].id],{value: JSON.stringify(custom)}]);
      return rpc('ir.config_parameter','create',[{key:'alvina.rrhh_turnos', value: JSON.stringify(custom)}]);
    });
}

function asignarHorario(empId, turno, descDia){
  // descDia: 0..6 o -1 (sin descanso)
  var nombre = 'Alviña · ' + turno.nombre + ' · ' +
    (descDia>=0 ? 'descansa '+DIAS_FULL[descDia].toLowerCase() : '7 días');
  // Buscar calendar existente con ese nombre
  return rpc('resource.calendar','search_read',[[['name','=',nombre]],['id']],{limit:1})
    .then(function(ex){
      if(ex.length) return ex[0].id;
      // Crear: una línea por cada día que SÍ trabaja
      var h1 = parseInt(turno.entra.slice(0,2)) + parseInt(turno.entra.slice(3,5))/60;
      var h2 = parseInt(turno.sale.slice(0,2))  + parseInt(turno.sale.slice(3,5))/60;
      var lineas = [];
      for(var d=0; d<7; d++){
        if(d===descDia) continue;
        lineas.push([0,0,{name:turno.nombre, dayofweek:String(d),
          hour_from:h1, hour_to:h2, day_period:'morning'}]);
      }
      return rpc('resource.calendar','create',[{
        name: nombre, hours_per_day: turno.hpd, tz:'America/Lima', attendance_ids: lineas
      }]);
    })
    .then(function(calId){
      return rpc('hr.employee','write',[[empId],{resource_calendar_id: calId}]);
    });
}

function paneHorarios(P){
  var h = guia('Acá se define a qué hora entra cada persona. De esto dependen las tardanzas. '+
    'Hay dos formas: <b>horario fijo</b>, que es el de siempre, y <b>turno variable</b>, que se '+
    'arma semana por semana en la aplicación Planificación de Odoo y manda sobre el fijo.');
  var resumen = S.cal.map(function(c){
    var lin = S.calLin.filter(function(l){ return l.calendar_id[0]===c.id && l.day_period!=='lunch'; });
    var ent = lin.length ? Math.min.apply(null, lin.map(function(l){ return l.hour_from; })) : null;
    var sal = lin.length ? Math.max.apply(null, lin.map(function(l){ return l.hour_to; })) : null;
    var dows = {}; lin.forEach(function(l){ dows[l.dayofweek]=1; });
    return {id:c.id, nombre:c.name, ent:ent, sal:sal, dias:Object.keys(dows).length,
      usa: P.filter(function(p){ return p.calId===c.id; }).length};
  }).filter(function(c){ return c.usa>0 || c.dias>0; }).sort(function(a,b){ return b.usa-a.usa; });

  h += '<div class="a-fix"><h3>Horarios fijos que existen</h3>'+
    '<p class="why">La hora de entrada de cada horario es la que se usa para medir tardanza.</p>'+
    '<div class="a-sc"><table class="a-t"><thead><tr><th>Horario</th><th>Entra</th><th>Sale</th>'+
    '<th>Días/semana</th><th>Personas</th></tr></thead><tbody>';
  resumen.forEach(function(c){
    h += '<tr><td class="nm">'+esc(c.nombre)+'</td>'+
      '<td class="hr">'+(c.ent!=null?minHHMM(c.ent*60):'—')+'</td>'+
      '<td class="hr">'+(c.sal!=null?minHHMM(c.sal*60):'—')+'</td>'+
      '<td class="hr">'+c.dias+'</td><td class="hr">'+c.usa+'</td></tr>';
  });
  h += '</tbody></table></div></div>';

  // -------- NUEVO: Asignar turno y descanso, agrupado por área --------
  var real = {};
  S.attRango.forEach(function(a){
    var ms=local(a.check_in), d=new Date(ms), min=d.getUTCHours()*60+d.getUTCMinutes();
    (real[a.employee_id[0]]=real[a.employee_id[0]]||[]).push(min);
  });
  function mediana(v){ var s=v.slice().sort(function(a,b){return a-b;}); return s[Math.floor(s.length/2)]; }

  // listado compacto de turnos disponibles
  var turnosTxt = TURNOS.map(function(t){ return t.nombre+' ('+t.entra+'–'+t.sale+')'; }).join(' · ');
  h += '<div class="a-fix" style="padding:13px 15px"><h3>Asignar turno y día de descanso</h3>'+
    '<p class="why">Elige un turno de la lista y el día que no trabaja. Si no existe en Odoo un '+
    'horario con esa combinación, se crea automáticamente. La hora real a la que marca aparece '+
    'al lado para ayudarte a elegir.<br><b style="color:var(--ink)">Turnos disponibles:</b> '+esc(turnosTxt)+'</p>'+
    '<div class="a-fl" style="margin-bottom:6px">'+buscador('h-q', S.hq, 'Buscar persona…')+
    '<button class="a-btn" id="h-nuevo" type="button">+ Nuevo turno</button></div>';
  if(S.nvoT){
    h += '<div class="a-asg" style="border-radius:7px;border:1px solid var(--ac);margin-bottom:10px">'+
      '<div class="a-edit-h"><div class="a-edit-t">Crear un turno nuevo</div>'+
        '<span class="sm">Queda disponible para toda la panadería</span></div>'+
      '<div class="a-asg-g">'+
        '<div class="a-asg-f"><label>Nombre del turno</label>'+
          '<input type="text" data-f="nombre" placeholder="Ej. Media jornada mañana"></div>'+
        '<div class="a-asg-f"><label>Hora de entrada</label>'+
          '<input type="time" data-f="entra" value="08:00"></div>'+
        '<div class="a-asg-f"><label>Hora de salida</label>'+
          '<input type="time" data-f="sale" value="14:00"></div>'+
      '</div>'+
      '<div class="a-asg-a">'+
        '<button class="a-btn" type="button" data-act="cancel-t">Cancelar</button>'+
        '<button class="a-btn a-btn-p" type="button" data-act="save-t">Guardar turno</button>'+
      '</div></div>';
  }

  var G = {};
  P.filter(function(p){ return !S.hq || p.nombre.toLowerCase().indexOf(S.hq.toLowerCase())>-1; })
    .forEach(function(p){ var k = p.area || '(Sin área)'; (G[k]=G[k]||[]).push(p); });
  var orden = Object.keys(G).sort(function(a,b){ return a.localeCompare(b); });

  orden.forEach(function(areaN){
    var lista = G[areaN].sort(function(a,b){ return a.nombre.localeCompare(b.nombre); });
    var ab = !!S.abAreas[areaN];
    h += '<div class="a-grp'+(ab?' on':'')+'" data-area="'+esc(areaN)+'">'+
         '<div class="a-grp-h" data-act="area">'+
         '<span class="ar">▸</span>'+esc(areaN)+
         '<span class="a-grp-n">'+lista.length+' persona'+(lista.length===1?'':'s')+'</span>'+
         '</div><div class="a-grp-body">';
    lista.forEach(function(p){
      var info = clasificarCalendar(p.calId);
      var rr = real[p.id] ? mediana(real[p.id]) : null;
      var ab = S.edith === p.id;
      var turnoTxt = info.turno ? info.turno.nombre+' ('+info.turno.entra+')' :
                     (p.horario ? p.horario : '— sin asignar —');
      var descTxt = info.descanso!=null ? DIAS_FULL[info.descanso] :
                    (p.calId ? 'todos los días' : '—');
      var sinH = !p.calId;
      h += '<div class="a-per'+(sinH?' sin':'')+'" data-emp="'+p.id+'">'+
        '<div class="a-per-nm">'+esc(p.nombre)+
          (rr!=null?'<div class="sm">Marca a las '+minHHMM(rr)+' en promedio</div>':'')+'</div>'+
        '<div class="a-per-t">Turno: <b>'+esc(turnoTxt)+'</b></div>'+
        '<div class="a-per-d">Descansa: <b>'+esc(descTxt)+'</b></div>'+
        '<button class="a-btn-s" type="button" data-act="toggle-h">'+(ab?'▾':'Cambiar')+'</button>'+
        '</div>';
      if(ab){
        h += '<div class="a-asg" data-emp="'+p.id+'">'+
          '<div class="a-asg-hint">'+(rr!=null?
            'Marca a las <b>'+minHHMM(rr)+'</b> en promedio. ':'')+
            'Si el turno que le corresponde no está en la lista, usa el más parecido y después lo '+
            'ajustamos desde Odoo.</div>'+
          '<div class="a-asg-g">'+
          '<div class="a-asg-f"><label>Turno</label><select data-f="turno">'+
            '<option value="">— elegir turno —</option>'+
            TURNOS.map(function(t){
              return '<option value="'+t.id+'"'+(info.turno&&info.turno.id===t.id?' selected':'')+
              '>'+t.nombre+' ('+t.entra+' – '+t.sale+')</option>';
            }).join('')+
          '</select></div>'+
          '<div class="a-asg-f"><label>Día de descanso</label><select data-f="desc">'+
            DIAS_FULL.map(function(n,i){
              return '<option value="'+i+'"'+(info.descanso===i?' selected':'')+'>'+n+'</option>';
            }).join('')+
            '<option value="-1"'+(info.descanso==null?' selected':'')+'>Sin descanso fijo (7 días)</option>'+
          '</select></div>'+
          '</div>'+
          '<div class="a-asg-a">'+
            '<button class="a-btn" type="button" data-act="cancel-h">Cancelar</button>'+
            '<button class="a-btn a-btn-p" type="button" data-act="save-h">Guardar</button>'+
          '</div></div>';
      }
    });
    h += '</div></div>';   // cerrar a-grp-body y a-grp
  });
  h += '</div>';

  h += '<div class="a-fix"><h3>Turnos variables de la semana</h3>'+
    '<p class="why">Se arman en la aplicación <b>Planificación</b> de Odoo. Un turno solo cuenta '+
    'para las tardanzas cuando está <b>publicado</b>; mientras está en borrador no se usa.</p>';
  if(!S.slots.length){
    h += '<div class="a-empty">No hay turnos cargados para la semana del '+larga(S.semana)+'.</div>';
  } else {
    h += '<div class="a-sc"><table class="a-t"><thead><tr><th>Empleado</th><th>Día</th>'+
      '<th>Desde</th><th>Hasta</th><th>Estado</th></tr></thead><tbody>';
    S.slots.forEach(function(s){
      var ci=local(s.start_datetime), co=local(s.end_datetime);
      h += '<tr><td class="nm">'+esc(s.employee_id?s.employee_id[1]:'—')+'</td>'+
        '<td>'+DIA3[new Date(ci).getUTCDay()]+' '+new Date(ci).getUTCDate()+'</td>'+
        '<td class="hr">'+hhmm(ci)+'</td><td class="hr">'+hhmm(co)+'</td>'+
        '<td>'+(s.state==='published' ? '<span class="pill p-ok">Publicado</span>'
                                      : '<span class="pill p-wa">Borrador</span>')+'</td></tr>';
    });
    h += '</tbody></table></div>';
  }
  h += '</div>';
  pane().innerHTML = h;
  ligarBuscador('h-q','hq');
  // botón nuevo turno + su formulario
  var bNvo = pane().querySelector('#h-nuevo');
  if(bNvo) bNvo.onclick = function(){ S.nvoT = !S.nvoT; pintar(); };
  var boxT = pane().querySelector('[data-act=save-t]');
  var boxC = pane().querySelector('[data-act=cancel-t]');
  if(boxC) boxC.onclick = function(){ S.nvoT = false; pintar(); };
  if(boxT) boxT.onclick = function(){
    var form = boxT.closest('.a-asg');
    var nombre = form.querySelector('[data-f=nombre]').value.trim();
    var entra  = form.querySelector('[data-f=entra]').value;
    var sale   = form.querySelector('[data-f=sale]').value;
    boxT.disabled = true; boxT.textContent = 'Guardando…';
    guardarTurnoNuevo(nombre, entra, sale)
      .then(function(){ mensaje('Turno «'+nombre+'» guardado.','ok'); S.nvoT = false; pintar(); })
      .catch(function(e){ boxT.disabled=false; boxT.textContent='Guardar turno';
        mensaje(e.message || 'No se pudo guardar.','cr'); });
  };

  // alternar apertura de cada área
  Array.prototype.forEach.call(pane().querySelectorAll('.a-grp-h[data-act=area]'), function(hd){
    hd.onclick = function(){
      var grp = hd.closest('.a-grp'); if(!grp) return;
      var area = grp.getAttribute('data-area');
      S.abAreas[area] = !S.abAreas[area]; pintar();
    };
  });
  // manejar clic en filas y formulario de asignación
  Array.prototype.forEach.call(pane().querySelectorAll('.a-per'), function(fila){
    var btn = fila.querySelector('[data-act=toggle-h]');
    if(btn) btn.onclick = function(){
      var id = +fila.getAttribute('data-emp');
      S.edith = S.edith===id ? null : id; pintar();
    };
  });
  Array.prototype.forEach.call(pane().querySelectorAll('.a-asg'), function(box){
    var emp = +box.getAttribute('data-emp');
    var bCanc = box.querySelector('[data-act=cancel-h]');
    var bSave = box.querySelector('[data-act=save-h]');
    if(bCanc) bCanc.onclick = function(){ S.edith = null; pintar(); };
    if(bSave) bSave.onclick = function(){
      var turnoId = box.querySelector('[data-f=turno]').value;
      var descId  = box.querySelector('[data-f=desc]').value;
      if(!turnoId){ mensaje('Elige un turno.','cr'); return; }
      var turno = TURNOS.filter(function(t){ return t.id===turnoId; })[0];
      var desc = parseInt(descId);
      bSave.disabled = true; bSave.textContent = 'Guardando…';
      asignarHorario(emp, turno, desc).then(function(){
        mensaje('Turno asignado.','ok'); S.edith = null; cargar();
      }).catch(function(e){
        bSave.disabled = false; bSave.textContent = 'Guardar';
        mensaje('No se pudo guardar: '+String(e.message).slice(0,160),'cr');
      });
    };
  });
}

function faltantes(p){
  var f=[];
  if(!p.dni) f.push('Documento');
  if(!p.cumple) f.push('Cumpleaños');
  if(!p.tel) f.push('Teléfono');
  if(!p.area) f.push('Área');
  if(!p.cargo) f.push('Cargo');
  if(!p.calId) f.push('Horario');
  return f;
}
function paneFicha(P){
  var CAMPOS=['Documento','Cumpleaños','Teléfono','Área','Cargo','Horario'];
  var h = guia('Qué dato le falta a cada ficha. Haz clic en una fila para completar los datos '+
    'de esa persona desde acá mismo: los campos que faltan salen marcados en rojo.');
  var comp = P.filter(function(p){ return faltantes(p).length===0; }).length;
  var cuenta={}; CAMPOS.forEach(function(c){
    cuenta[c] = P.filter(function(p){ return faltantes(p).indexOf(c)>-1; }).length; });
  h += '<div class="a-fix"><h3>'+comp+' de '+P.length+' fichas están completas</h3>'+
    '<p class="why">Cada dato que falta es algo que Recursos Humanos tiene que recabar del trabajador.</p><ul>';
  CAMPOS.forEach(function(c){ if(cuenta[c]) h+='<li>'+c+' — <b>'+cuenta[c]+'</b></li>'; });
  h += '</ul></div>';
  h += '<div class="a-fl">'+buscador('g-q', S.gq, 'Buscar persona…')+
    sel('g-falta',S.gfalta,'Todos los datos',CAMPOS)+
    '<button class="a-btn" id="g-csv" type="button">Exportar lo que falta</button></div>';
  var L = P.filter(function(p){
    var f=faltantes(p);
    if(S.gfalta && f.indexOf(S.gfalta)<0) return false;
    if(S.gq && p.nombre.toLowerCase().indexOf(S.gq.toLowerCase())<0) return false;
    return true;
  }).sort(function(a,b){ return faltantes(b).length-faltantes(a).length; });
  h += '<div class="a-card"><div class="a-sc"><table class="a-t"><thead><tr>'+
    '<th>Empleado</th><th>Sede</th><th>Doc.</th><th>Cumpleaños</th><th>Teléfono</th>'+
    '<th>Área</th><th>Cargo</th><th>Horario</th><th>Estado</th><th></th>'+
    '</tr></thead><tbody>';
  if(!L.length) h += '<tr><td colspan="10"><div class="a-empty">Nadie coincide.</div></td></tr>';
  L.forEach(function(p){
    var f = faltantes(p);
    var pil = f.length===0 ? '<span class="pill p-ok">Completa</span>'
            : f.length<=2 ? '<span class="pill p-wa">'+f.length+' por llenar</span>'
            : '<span class="pill p-cr">'+f.length+' por llenar</span>';
    var ab = S.edit === p.id;
    h += '<tr class="cl" data-emp="'+p.id+'"><td><div class="nm">'+esc(p.nombre)+'</div></td>'+
      '<td>'+esc(p.sede||'—')+'</td>'+
      cel(p.dni)+cel(p.cumple)+cel(p.tel)+cel(p.area)+cel(p.cargo)+cel(p.horario)+
      '<td>'+pil+'</td><td class="hr">'+(ab?'▾':'✎')+'</td></tr>';
    if(ab) h += '<tr><td colspan="10" class="det" style="padding:0">'+formularioFicha(p)+'</td></tr>';
  });
  h += '</tbody></table></div></div>';
  pane().innerHTML = h;
  ligarBuscador('g-q','gq');
  var s=pane().querySelector('#g-falta');
  if(s) s.onchange=function(){ S.gfalta=s.value; pintar(); };
  var b=pane().querySelector('#g-csv');
  if(b) b.onclick=function(){
    bajarCSV('fichas_incompletas.csv',
      [['Empleado','Sede','Documento','Cumpleanos','Telefono','Area','Cargo','Horario','Falta']],
      P.filter(function(p){ return faltantes(p).length; }).map(function(p){
        return [p.nombre,p.sede||'',p.dni||'',p.cumple||'',p.tel||'',p.area||'',
                p.cargo||'',p.horario||'',faltantes(p).join(', ')]; }));
  };
  Array.prototype.forEach.call(pane().querySelectorAll('tr.cl'), function(tr){
    tr.onclick = function(ev){
      if(ev.target.closest('.a-edit')) return;      // no cerrar al interactuar dentro del form
      var id = +tr.getAttribute('data-emp');
      S.edit = S.edit===id ? null : id; pintar();
    };
  });
  ligarFormulario();
}
function cel(v){ return v ? '<td>'+esc(v)+'</td>' : '<td><span class="pill p-cr">Falta</span></td>'; }

function formularioFicha(p){
  var f = faltantes(p);
  var fal = function(c){ return f.indexOf(c)>-1 ? ' falta' : ''; };
  var depOpts = (S.dept||[]).map(function(d){ return [d.id, d.complete_name||d.name]; });
  var calOpts = (S.cal||[]).map(function(c){ return [c.id, c.name]; });
  return '<div class="a-edit" data-emp="'+p.id+'">'+
    '<div class="a-edit-h"><div class="a-edit-t">Datos de '+esc(p.nombre)+'</div>'+
      '<span class="sm">Lo rojo es lo que falta</span></div>'+
    '<div class="a-edit-g">'+
      campoInput('dni', 'Documento', p.dni||'', 'Ej. 48462726', fal('Documento'))+
      campoInput('cumple', 'Cumpleaños', p.cumple||'', '', fal('Cumpleaños'), 'date')+
      campoInput('tel', 'Teléfono', p.tel||'', '+51 9XX XXX XXX', fal('Teléfono'))+
      campoSelect('dept', 'Área', p.deptId, depOpts, fal('Área'))+
      campoInput('cargo', 'Cargo', p.cargo||'', 'Ej. Cajero/a', fal('Cargo'))+
      campoSelect('cal', 'Horario', p.calId, calOpts, fal('Horario'))+
    '</div>'+
    '<div class="a-edit-a">'+
      '<button class="a-btn" type="button" data-act="cancel">Cancelar</button>'+
      '<button class="a-btn a-btn-p" type="button" data-act="save">Guardar cambios</button>'+
    '</div></div>';
}
function campoInput(id, lbl, val, ph, extra, tipo){
  return '<div class="a-edit-f'+extra+'"><label>'+lbl+'</label>'+
    '<input type="'+(tipo||'text')+'" data-f="'+id+'" value="'+esc(val)+'" placeholder="'+ph+'"></div>';
}
function campoSelect(id, lbl, val, opts, extra){
  var h = '<div class="a-edit-f'+extra+'"><label>'+lbl+'</label><select data-f="'+id+'">'+
    '<option value="">— sin asignar —</option>';
  opts.forEach(function(o){
    h += '<option value="'+o[0]+'"'+(String(val)===String(o[0])?' selected':'')+'>'+esc(o[1])+'</option>'; });
  return h + '</select></div>';
}
function ligarFormulario(){
  var box = pane().querySelector('.a-edit');
  if(!box) return;
  var emp = +box.getAttribute('data-emp');
  box.addEventListener('click', function(e){ e.stopPropagation(); });   // los clics internos no cierran la fila
  var btnCancel = box.querySelector('[data-act=cancel]');
  var btnSave   = box.querySelector('[data-act=save]');
  if(btnCancel) btnCancel.onclick = function(){ S.edit = null; pintar(); };
  if(btnSave) btnSave.onclick = function(){
    var vals = {};
    var g = function(f){ var el=box.querySelector('[data-f='+f+']'); return el?el.value.trim():''; };
    vals.dni = g('dni'); vals.cumple = g('cumple'); vals.tel = g('tel');
    vals.cargo = g('cargo'); vals.dept = g('dept'); vals.cal = g('cal');

    if(vals.dni && !/^[0-9]{8,12}$/.test(vals.dni)){
      return mensaje('El documento debe tener solo números (8 a 12 dígitos).', 'cr');
    }

    var pay = {};
    pay.identification_id = vals.dni || false;
    pay.birthday = vals.cumple || false;
    pay.private_phone = vals.tel || false;
    pay.job_title = vals.cargo || false;
    pay.department_id = vals.dept ? +vals.dept : false;
    pay.resource_calendar_id = vals.cal ? +vals.cal : false;

    btnSave.disabled = true; btnSave.textContent = 'Guardando…';
    rpc('hr.employee','write',[[emp], pay], {})
      .then(function(){ mensaje('Ficha guardada.', 'ok'); S.edit = null; cargar(); })
      .catch(function(e){
        btnSave.disabled = false; btnSave.textContent = 'Guardar cambios';
        mensaje('No se pudo guardar: '+String(e.message).slice(0,140), 'cr');
      });
  };
}
function mensaje(txt, cl){
  var ex = document.querySelector('.a-msg'); if(ex) ex.remove();
  var d = document.createElement('div');
  d.className = 'a-msg ' + cl;
  d.textContent = txt;
  document.body.appendChild(d);
  setTimeout(function(){ d.style.transition='opacity .3s'; d.style.opacity=0;
    setTimeout(function(){ d.remove(); }, 400); }, 3000);
}

function paneAlertas(P, jor){
  var h = guia('Lo que hay que resolver hoy mismo. Acá puedes cerrar una jornada abierta o '+
    'registrar un descanso sin salir de esta pantalla. Una jornada que queda sin salida bloquea '+
    'todas las marcas siguientes de esa persona, así que conviene revisarlas a diario.');
  // ids de los hr.attendance abiertos para poder cerrarlos
  var attAbierta = {};
  S.att.forEach(function(a){
    if(!a.check_out) attAbierta[a.employee_id[0]] = {id:a.id, ci:a.check_in};
  });
  var sinSalida = P.filter(function(p){ return jor[p.id] && !jor[p.id].co; });
  var noMarco = P.filter(function(p){ return !jor[p.id] && !deDescanso(p, S.fecha) &&
                                              p.calId && yaDebioEntrar(p); });
  var descanso = P.filter(function(p){ return deDescanso(p, S.fecha); });
  h += '<div class="a-kpis">'+
    kpi('No marcaron', noMarco.length, 'y ya debían entrar', noMarco.length?'cr':'ok')+
    kpi('De descanso', descanso.length, 'registrado en Odoo','')+
  '</div>';

  // ----- No marcaron con botón descanso/falta -----
  if(noMarco.length){
    h += '<div class="a-fix"><h3>No marcaron hoy</h3>'+
      '<p class="why">Su hora de entrada pasó hace más de media hora y no hay descanso registrado. '+
      'Si estaban de franco, <b>«Registrar descanso»</b> crea la ausencia del día y deja de contar '+
      'como falta. <b>«Marcar como falta»</b> la registra como falta justificada (igual no afecta '+
      'tardanzas, pero queda el rastro).</p>';
    noMarco.forEach(function(p){
      var esp = esperada(p, S.fecha);
      h += '<div class="a-row" data-emp="'+p.id+'">'+
        '<div class="a-row-info"><div class="a-row-nm">'+esc(p.nombre)+'</div>'+
        '<div class="a-row-sub">Debía entrar '+(esp?minHHMM(esp.min):'—')+' · '+esc(p.sede||'—')+'</div></div>'+
        '<div class="a-row-act">'+
        '<button class="a-btn-s ok" type="button" data-act="descanso">Descanso</button>'+
        '<button class="a-btn-s" type="button" data-act="falta">Falta</button>'+
        '</div></div>';
    });
    h += '</div>';
  }

  // ----- De descanso (informativo) -----
  if(descanso.length){
    h += '<div class="a-fix"><h3>De descanso hoy</h3>'+
      '<p class="why">Tienen una ausencia registrada, así que no cuentan como falta ni como tardanza.</p>'+
      '<ul><li>'+descanso.map(function(p){
        return esc(p.nombre)+'<span class="sm"> · '+esc(p.sede||'')+'</span>'; }).join('</li><li>')+'</li></ul></div>';
  }

  if(!noMarco.length && !descanso.length)
    h += '<div class="a-card"><div class="a-empty">Nada pendiente por hoy.</div></div>';

  pane().innerHTML = h;

  // acciones
  Array.prototype.forEach.call(pane().querySelectorAll('.a-row'), function(fila){
    var emp = +fila.getAttribute('data-emp');
    Array.prototype.forEach.call(fila.querySelectorAll('[data-act]'), function(btn){
      btn.onclick = function(){
        var act = btn.getAttribute('data-act');
        var nombre = fila.querySelector('.a-row-nm').textContent;
        if(act==='cerrar'){
          if(!confirm('Cerrar la jornada abierta de ' + nombre + ' con 0 horas? '+
                      'La persona podrá volver a marcar desde su próxima entrada.')) return;
          var attId = +fila.getAttribute('data-att');
          var ci = attAbierta[emp].ci;
          // check_out = check_in + 1 segundo, así queda visible como "sin salida real"
          var co = new Date(new Date(ci.replace(' ','T')+'Z').getTime()+1000);
          var out = co.toISOString().slice(0,19).replace('T',' ');
          btn.disabled = true; btn.textContent = '…';
          rpc('hr.attendance','write',[[attId],{check_out:out}])
            .then(function(){ mensaje('Jornada cerrada. '+nombre+' está desbloqueado.','ok'); cargar(); })
            .catch(function(e){ btn.disabled=false; btn.textContent='Cerrar con 0 h';
              mensaje('No se pudo cerrar: '+String(e.message).slice(0,140),'cr'); });
        }
        else if(act==='descanso' || act==='falta'){
          var tipoId = act==='descanso' ? 1 : 4;   // 1=Descanso, 4=Falta
          var tipoNombre = act==='descanso' ? 'descanso' : 'falta';
          if(!confirm('Registrar '+tipoNombre+' para ' + nombre + ' del día de hoy?')) return;
          btn.disabled = true; btn.textContent = '…';
          rpc('hr.leave','create',[{employee_id: emp, holiday_status_id: tipoId,
              request_date_from: S.fecha, request_date_to: S.fecha,
              name: 'Registrado desde Personal'}])
            .then(function(id){
              // intentar aprobar automáticamente para que surta efecto
              return rpc('hr.leave','action_validate',[[id]]).catch(function(){ return true; });
            })
            .then(function(){ mensaje(nombre+' queda registrado como '+tipoNombre+'.','ok'); cargar(); })
            .catch(function(e){ btn.disabled=false; btn.textContent = act==='descanso'?'Descanso':'Falta';
              mensaje('No se pudo registrar: '+String(e.message).slice(0,160),'cr'); });
        }
      };
    });
  });
}

function bajarCSV(nombre, cab, filas){
  var out = cab.concat(filas);
  var txt = String.fromCharCode(0xFEFF) + out.map(function(l){
    return l.map(function(c){ return '"'+String(c==null?'':c).replace(/"/g,'""')+'"'; }).join(';');
  }).join('\r\n');
  var a = document.createElement('a');
  a.href = URL.createObjectURL(new Blob([txt],{type:'text/csv;charset=utf-8'}));
  a.download = nombre;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
}

document.getElementById('a-rf').onclick = cargar;
cargar();
})();
